import { describe, expect, it } from 'vitest';
import { Add, Dummy, Mul, Pow, Rational, Sym, add, andrePoly, bernoulliCPoly, bernoulliPoly, dummyEq, eulerPoly, factor, genocchiPoly, mul, pow } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.polys.appellseqs", () => {
  it("andre_poly(9, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(andrePoly(9, x))).toBe('x**9 - 36*x**7 + 630*x**5 - 5124*x**3 + 12465*x');
  });
  it("bernoulli_poly(5, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(bernoulliPoly(5, x))).toBe('x**5 - 5*x**4/2 + 5*x**3/3 - x/6');
  });
  // the arguments do not type-check against the public API
  //   summation(x**4, (x, -6, 27))
  //   => 3144337
  it.todo("summation(x**4, (x, -6, 27))");
  it("psum(1, 1, x).factor()", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(Rational.of(-1n, 2n, { gcd: 1n }), mul(Rational.of(1n, 2n, { gcd: 1n }), pow(add(Rational.of(1n, 1n, { gcd: 1n }), x), Rational.of(2n, 1n, { gcd: 1n }))), mul(Rational.of(-1n, 2n, { gcd: 1n }), x))))).toBe('x*(x + 1)/2');
  });
  it("psum(2, 1, x).factor()", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(Rational.of(1n, 6n, { gcd: 1n }), mul(Rational.of(-1n, 2n, { gcd: 1n }), pow(add(Rational.of(1n, 1n, { gcd: 1n }), x), Rational.of(2n, 1n, { gcd: 1n }))), mul(Rational.of(1n, 3n, { gcd: 1n }), pow(add(Rational.of(1n, 1n, { gcd: 1n }), x), Rational.of(3n, 1n, { gcd: 1n }))), mul(Rational.of(1n, 6n, { gcd: 1n }), x))))).toBe('x*(x + 1)*(2*x + 1)/6');
  });
  it("psum(3, 1, x).factor()", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(mul(Rational.of(-1n, 2n, { gcd: 1n }), pow(add(Rational.of(1n, 1n, { gcd: 1n }), x), Rational.of(3n, 1n, { gcd: 1n }))), mul(Rational.of(1n, 4n, { gcd: 1n }), pow(add(Rational.of(1n, 1n, { gcd: 1n }), x), Rational.of(2n, 1n, { gcd: 1n }))), mul(Rational.of(1n, 4n, { gcd: 1n }), pow(add(Rational.of(1n, 1n, { gcd: 1n }), x), Rational.of(4n, 1n, { gcd: 1n }))))))).toBe('x**2*(x + 1)**2/4');
  });
});

